def compute(vars):
    change = vars["v2"] - vars["v1"]
    return {
        "value": change,
        "trace": {
            "ownership_interest_2018": vars["v1"],
            "ownership_interest_2019": vars["v2"],
            "change": change,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
